<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRealtimeRefresh } from '../composables/useRealtimeRefresh'
const report=ref<any>({companies:[],totals:{ExpectedSites:0,CompletedSites:0,PendingSites:0,MissingDtrSites:0,Percent:null,UnconfiguredSites:0},cutoffs:[],period:null})
const cutoff=ref(''),loading=ref(true),refreshing=ref(false),error=ref(''),expanded=ref<string|null>(null)
let request=0,controller:AbortController|null=null
const totalPercent=computed(()=>report.value.totals.Percent===null?'—':`${report.value.totals.Percent}%`)
const key=(company:any,group:any)=>`${company.AgencyID}:${group.SiteAccountID}`
const span=(company:any)=>company.groups.length+(company.groups.some((group:any)=>key(company,group)===expanded.value)?1:0)
const day=(value:string)=>new Date(value+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'})
const periodLabel=(period:any)=>`${day(period.PeriodStart)} – ${day(period.PeriodEnd)}`
async function load(silent=false){
  const current=++request
  controller?.abort();controller=new AbortController()
  refreshing.value=true;if(!silent)loading.value=true;error.value=''
  try{
    const [periodStart,periodEnd]=cutoff.value.split(':')
    const result=await $fetch<any>('/api/dashboard/payroll-progress',{query:periodStart?{periodStart,periodEnd}:{},signal:controller.signal,timeout:15000,retry:0})
    if(current!==request)return
    report.value=result;cutoff.value=`${result.period.PeriodStart}:${result.period.PeriodEnd}`
  }catch(cause:any){if(current===request){error.value=cause?.data?.statusMessage||'Payroll progress could not be refreshed.';if(report.value.period)cutoff.value=`${report.value.period.PeriodStart}:${report.value.period.PeriodEnd}`}}
  finally{if(current===request){loading.value=false;refreshing.value=false}}
}
function changeCutoff(){expanded.value=null;void load()}
onMounted(()=>load())
onBeforeUnmount(()=>{request++;controller?.abort()})
useRealtimeRefresh(()=>load(true),{shouldRefresh:()=>!refreshing.value})
</script>
<template>
 <section class="payroll-run-progress" aria-labelledby="payroll-run-progress-title">
  <header class="progress-heading"><div><p>PAYROLL MONITORING</p><h2 id="payroll-run-progress-title">Payroll Run Progress</h2><span>Finalized site payrolls by company and client group.</span></div><div class="progress-controls"><label>Payroll cutoff<select v-model="cutoff" :disabled="loading&&!report.cutoffs.length" @change="changeCutoff"><option v-if="!report.cutoffs.length" value="">Loading cutoffs…</option><option v-for="period in report.cutoffs" :key="period.PeriodStart+period.PeriodEnd" :value="period.PeriodStart+':'+period.PeriodEnd">{{periodLabel(period)}}</option></select></label><button type="button" :disabled="refreshing" @click="load()">Refresh</button></div></header>
  <p class="progress-explainer">Completed means finalized payroll. Expected sites follow current company assignments; sites without a DTR remain pending.</p>
  <p v-if="error" class="progress-error" role="alert">{{error}} <span v-if="report.period">The last loaded results are shown.</span></p>
  <p v-if="report.totals.UnconfiguredSites" class="progress-warning" role="status">{{report.totals.UnconfiguredSites}} active sites have no company assignment or DTR for this cutoff. Complete their site setup to calculate overall progress.</p>
  <div class="progress-overview" :aria-busy="loading"><div><strong>{{loading?'—':totalPercent}}</strong><span>Overall progress</span></div><p><b>{{loading?'—':report.totals.CompletedSites}}</b> / {{loading?'—':report.totals.ExpectedSites}} configured site payrolls finalized</p><span>{{loading?'—':report.totals.PendingSites}} pending · {{loading?'—':report.totals.MissingDtrSites}} without DTR</span></div>
  <div class="progress-table-wrap"><table><thead><tr><th>Company</th><th>Client Group</th><th>Progress</th><th>Finalized / expected</th><th>Pending</th><th>Without DTR</th></tr></thead><tbody>
   <tr v-if="loading"><td colspan="6" class="empty-progress">Loading payroll progress…</td></tr><tr v-else-if="!report.companies.length"><td colspan="6" class="empty-progress">No site payrolls are expected from the current assignments. Assign sites to companies under Organization > Site.</td></tr>
   <template v-for="company in loading?[]:report.companies" :key="company.AgencyID"><template v-for="(group,index) in company.groups" :key="group.SiteAccountID">
    <tr><td v-if="index===0" :rowspan="span(company)" class="company-cell"><strong>{{company.AgencyName}}</strong><small>{{company.CompletedSites}} / {{company.ExpectedSites}} finalized</small><b>{{company.Percent===null?'—':company.Percent+'%'}}</b></td><td><strong>{{group.SiteAccountName}}</strong><small v-if="!group.SiteAccountID">Choose a Site Account in Organization > Site.</small></td><td><div class="group-progress"><div class="progress-track" role="progressbar" :aria-label="company.AgencyName+' – '+group.SiteAccountName" :aria-valuenow="group.Percent||0" :aria-valuemin="0" :aria-valuemax="100"><span :class="{complete:group.Percent===100}" :style="{width:(group.Percent||0)+'%'}"></span></div><strong>{{group.Percent===null?'—':group.Percent+'%'}}</strong></div></td><td><button type="button" class="site-count-button" :aria-expanded="expanded===key(company,group)" @click="expanded=expanded===key(company,group)?null:key(company,group)">{{group.CompletedSites}} / {{group.ExpectedSites}} sites <span aria-hidden="true">{{expanded===key(company,group)?'▴':'▾'}}</span></button></td><td>{{group.PendingSites}}</td><td>{{group.MissingDtrSites}}</td></tr>
    <tr v-if="expanded===key(company,group)"><td colspan="5" class="progress-site-details"><ul><li v-for="site in group.sites" :key="site.SiteID"><span>{{site.SiteName}}</span><span class="site-progress-status" :class="{finalized:site.Status==='Finalized'}">{{site.Status}}</span></li></ul></td></tr>
   </template></template>
  </tbody></table></div>
 </section>
</template>
<style scoped>
.payroll-run-progress{--progress-line:#dce5f2;--progress-surface:#fff;--progress-muted:#657d9d;--progress-ink:#17365b;--progress-soft:#f2f8fc;margin:0 0 24px;border:1px solid var(--progress-line);border-radius:16px;background:var(--progress-surface);color:var(--progress-ink);overflow:hidden}.progress-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 26px 16px}.progress-heading p{margin:0;color:#2864e8;font-size:.67rem;letter-spacing:.08em;font-weight:800}.progress-heading h2{margin:5px 0 7px;font-size:1.25rem}.progress-heading>div>span{font-size:.79rem;color:var(--progress-muted)}.progress-controls{display:flex;align-items:end;gap:10px}.progress-controls label{display:grid;gap:7px;color:var(--progress-muted);font-size:.74rem;font-weight:700}.progress-controls select{box-sizing:border-box;min-width:260px;min-height:42px;padding:9px 32px 9px 12px;border:1px solid var(--progress-line);border-radius:9px;background:var(--progress-surface);color:var(--progress-ink);font:inherit}.progress-controls button{min-height:42px;padding:9px 13px;border:1px solid var(--progress-line);border-radius:9px;background:var(--progress-soft);color:var(--progress-ink);font:inherit;font-size:.78rem;cursor:pointer}.progress-controls button:disabled{opacity:.55;cursor:wait}.progress-explainer,.progress-error,.progress-warning{margin:0 26px 18px;font-size:.77rem;line-height:1.5;color:var(--progress-muted)}.progress-error{color:#b42318}.progress-warning{padding:12px;border-radius:9px;background:#fff3da;color:#946200}.progress-overview{display:flex;align-items:center;gap:24px;margin:0 26px 20px;padding:16px 18px;border:1px solid var(--progress-line);border-radius:11px;background:var(--progress-soft)}.progress-overview>div{display:grid;gap:3px;min-width:110px}.progress-overview>div>strong{font-size:1.55rem;color:#2864e8}.progress-overview>div>span,.progress-overview>span{font-size:.73rem;color:var(--progress-muted)}.progress-overview p{margin:0;flex:1;font-size:.82rem;line-height:1.5}.progress-table-wrap{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse;text-align:left;table-layout:auto}th,td{padding:16px 20px;border-top:1px solid var(--progress-line);font-size:.8rem;vertical-align:middle}th{font-size:.68rem;color:var(--progress-muted);text-transform:uppercase;letter-spacing:.025em;background:var(--progress-soft)}td small{display:block;margin-top:7px;color:var(--progress-muted);font-size:.7rem;line-height:1.5}.company-cell{width:21%;max-width:230px;background:var(--progress-soft);border-right:1px solid var(--progress-line)}.company-cell>strong{display:block;line-height:1.5}.company-cell>b{display:inline-block;margin-top:11px;font-size:.94rem;color:#2864e8}.group-progress{display:flex;align-items:center;gap:12px;min-width:170px}.group-progress>strong{min-width:47px;text-align:right;font-size:.8rem}.progress-track{height:9px;flex:1;min-width:105px;border-radius:9px;background:#e7edf6;overflow:hidden}.progress-track>span{display:block;height:100%;border-radius:inherit;background:#3475ed;transition:width .2s ease}.progress-track>span.complete{background:#18a46b}.site-count-button{border:0;background:transparent;color:#245cce;font:inherit;white-space:nowrap;cursor:pointer;padding:7px 0}.site-count-button>span{margin-left:6px}.progress-site-details{background:var(--progress-soft)}.progress-site-details ul{display:grid;gap:7px;list-style:none;margin:0;padding:0}.progress-site-details li{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:7px 0;font-size:.77rem}.site-progress-status{flex:none;padding:5px 9px;border-radius:16px;background:#fff0d7;color:#946200;font-size:.7rem}.site-progress-status.finalized{background:#dcf6e9;color:#117b4a}.empty-progress{padding:28px;text-align:center;color:var(--progress-muted)}@media(max-width:1000px){.progress-heading{align-items:flex-start;flex-direction:column}.progress-controls{width:100%}.progress-controls label{flex:1}.progress-controls select{width:100%;min-width:0}.progress-overview{gap:15px;flex-wrap:wrap}.progress-overview>span{width:100%}}@media(max-width:600px){.progress-heading{padding:20px 16px 14px}.progress-explainer,.progress-error,.progress-warning{margin-left:16px;margin-right:16px}.progress-overview{margin-left:16px;margin-right:16px;padding:14px}.progress-overview p{font-size:.77rem}.progress-controls button{font-size:.74rem}.progress-overview>div{min-width:95px}.progress-overview>div>strong{font-size:1.35rem}}@media(prefers-reduced-motion:reduce){.progress-track>span{transition:none}}
:global(html[data-theme='dark']) .payroll-run-progress{--progress-line:#334562;--progress-surface:#15223b;--progress-muted:#a1b2cd;--progress-ink:#d8e6f8;--progress-soft:#1c2e4b}
</style>
